<form method="post" action="/order" data-order-form><?=csrfField()?><input type="hidden" name="submission_key" value="<?=h($nonce)?>"><div class="order-layout"><div><h2><?=t('Состав заказа','Your selection')?></h2><?php foreach($products as $product):$qty=$old['qty'][$product['id']]??((int)($_GET['product']??0)===(int)$product['id']?1:0);?><div class="order-row"><img src="<?=h($product['image'])?>" alt="<?=h(tr($product))?>" width="90" height="80"><div><a href="/catalog/product/<?=$product['id']?>"><?=h(tr($product))?></a><span class="small"><?=h($product['subtype_'.lang()])?> · <?=h(money((int)$product['price_minor']))?></span></div><label><span class="small"><?=t('Количество','Quantity')?></span><input aria-label="<?=h(tr($product))?> — <?=t('количество','quantity')?>" type="number" name="qty[<?=$product['id']?>]" min="0" max="20" step="1" value="<?=h(is_scalar($qty)?$qty:0)?>" required></label></div><?php endforeach;?><label class="check"><input type="checkbox" name="delivery" value="1" <?=!empty($old['delivery'])?'checked':''?> data-delivery> <?=t('Доставка','Delivery')?> — <?=h(money((int)config('delivery_minor')))?></label><label><?=t('Адрес доставки','Delivery address')?><input name="address" maxlength="250" value="<?=h(is_string($old['address']??'')?$old['address']:'')?>" data-address autocomplete="street-address"></label></div><aside class="order-summary"><h2><?=t('Данные заказчика','Your details')?></h2><label><?=t('Имя и фамилия','Full name')?><input name="name" required minlength="2" maxlength="120" autocomplete="name" value="<?=h(is_string($old['name']??'')?$old['name']:'')?>"></label><label>Email<input name="email" type="email" required maxlength="190" autocomplete="email" value="<?=h(is_string($old['email']??'')?$old['email']:'')?>"></label><label><?=t('Телефон','Phone')?><input name="phone" type="tel" required pattern="\+?[0-9 ()\-]{7,25}" maxlength="25" autocomplete="tel" placeholder="+7 900 000-00-00" value="<?=h(is_string($old['phone']??'')?$old['phone']:'')?>"></label><label><?=t('Комментарий','Comment')?><textarea name="comment" rows="3" maxlength="2000"><?=h(is_string($old['comment']??'')?$old['comment']:'')?></textarea></label><div class="order-total"><span><?=t('Итого','Total')?></span><strong data-total aria-live="polite"><?=t('Выберите товары','Select items')?></strong></div><p class="small" data-quote-message></p><label class="check"><input type="checkbox" name="consent" value="1" required <?=isset($old['consent'])?'checked':''?>> <span><?=t('Согласен на обработку данных для оформления заказа.','I consent to data processing for this order.')?></span></label><button class="button" type="submit"><?=t('Отправить заказ','Submit order')?> ↗</button><noscript><p><?=t('Итоговая стоимость появится после отправки заказа.','Your total will be shown after submitting the order.')?></p></noscript></aside></div></form>
